window.VO = [{"id":"n01","text":"You're the guard at this gate, and whoever you point at tonight goes to jail.","at":0.24,"t0":0.12,"t1":5.575},{"id":"n02","text":"Ask this delivery man his name.","at":11.65,"t0":5.825,"t1":8.007},{"id":"a01","text":"Ravi, sir.","at":16.412,"t0":8.206,"t1":8.933},{"id":"n03","text":"Write it down.","at":18.268,"t0":9.134,"t1":10.225},{"id":"n04","text":"Now ask which flat.","at":21.55,"t0":10.775,"t1":12.23},{"id":"b01","text":"Three zero two.","at":24.758,"t0":12.379,"t1":13.47},{"id":"n05","text":"Write that too.","at":27.34,"t0":13.67,"t1":14.761},{"id":"n06","text":"Now check his parcel.","at":30.622,"t0":15.311,"t1":16.766},{"id":"c01","text":"Here, sir.","at":33.93,"t0":16.965,"t1":17.692},{"id":"n07","text":"Does the label match your book?","at":35.886,"t0":17.943,"t1":20.125},{"id":"n08","text":"It doesn't. Good catch.","at":42.95,"t0":21.475,"t1":22.93},{"id":"d01","text":"Sorry, sir. Wrong gate.","at":46.458,"t0":23.229,"t1":24.684},{"id":"n09","text":"So nobody got past you.","at":50.168,"t0":25.084,"t1":26.902},{"id":"n10","text":"Then who robbed flat three zero two?","at":54.304,"t0":27.152,"t1":29.697},{"id":"n11","text":"Police have four men in that jacket.","at":59.794,"t0":29.897,"t1":32.442},{"id":"n12","text":"Point at yours, and he goes to jail.","at":65.286,"t0":32.643,"t1":35.552},{"id":"n13","text":"Which one? You looked right at him.","at":71.504,"t0":35.752,"t1":38.297},{"id":"n14","text":"You're right. He was at your gate.","at":81.794,"t0":40.897,"t1":43.442},{"id":"n15","text":"He gave you the name.","at":87.686,"t0":43.843,"t1":45.661},{"id":"n16","text":"He gave you the flat.","at":91.622,"t0":45.811,"t1":47.629},{"id":"n17","text":"He put down the parcel.","at":95.558,"t0":47.779,"t1":49.597},{"id":"n18","text":"And he said sorry.","at":99.494,"t0":49.747,"t1":51.202},{"id":"n19","text":"Every time you looked down, one walked in, and the next stepped up.","at":104.104,"t0":52.052,"t1":56.779},{"id":"n20","text":"So you've just sent one to jail, and three of them home.","at":114.358,"t0":57.179,"t1":61.543},{"id":"n21","text":"You checked his name, his flat, his parcel, but you never checked his face.","at":124.086,"t0":62.043,"t1":67.134},{"id":"n22","text":"Psychologists did this to real people in 1998.","at":135.468,"t0":67.734,"t1":70.643},{"id":"n23","text":"One woman who missed it said she'd just seen a construction worker.","at":141.686,"t0":70.843,"t1":75.207},{"id":"n24","text":"You just saw a jacket.","at":151.012,"t0":75.506,"t1":77.324},{"id":"n25","text":"So who brought your last parcel?","at":155.65,"t0":77.825,"t1":80.007},{"id":"n26","text":"You looked right at him.","at":160.612,"t0":80.306,"t1":82.124},{"id":"n27","text":"What did he look like?","at":164.95,"t0":82.475,"t1":84.293}];
